using Essco.Application.Payroll;using Essco.Application.Security;using Essco.Domain.Payroll;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Payroll;
[Authorize(Policy=Permissions.Payroll)]public sealed class DetailModel(PayrollService service,PayrollBankFileService bankFiles):PageModel
{public PayrollRun Payroll{get;private set;}=null!;[TempData]public string?StatusMessage{get;set;}public async Task<IActionResult>OnGetAsync(int number,CancellationToken t){var x=await service.GetAsync(number,t);if(x is null)return NotFound();Payroll=x;return Page();}public async Task<IActionResult>OnPostFinalizeAsync(int number,CancellationToken t){var r=await service.FinalizeAsync(number,t);StatusMessage=r.Succeeded?"Planilla finalizada.":r.Error;return RedirectToPage(new{number});}public async Task<IActionResult>OnPostCancelAsync(int number,CancellationToken t){var r=await service.CancelAsync(number,t);StatusMessage=r.Succeeded?"Planilla anulada.":r.Error;return RedirectToPage(new{number});}public async Task<IActionResult>OnPostBankFileAsync(int number,DateOnly?applicationDate,CancellationToken t){var result=await bankFiles.GenerateAsync(number,applicationDate??DateOnly.FromDateTime(DateTime.Today),t);if(!result.Succeeded){StatusMessage=result.Error;return RedirectToPage(new{number});}return File(result.Content,"text/plain; charset=utf-8",$"Planilla_{number}.txt");}}
